(() => {
    const RESOURCE = typeof GetParentResourceName === 'function' ? GetParentResourceName() : 'kipchak_radar';
    const ANTENNAS = ['front', 'rear'];
    const COLOR_VARS = {
        Background: '--rd-bg',
        Border: '--rd-border',
        Text: '--rd-text',
        Muted: '--rd-muted',
        Digits: '--rd-digit',
        Front: '--rd-front',
        Rear: '--rd-rear',
        Alert: '--rd-alert',
        Lock: '--rd-lock',
        Bolo: '--rd-bolo',
        Crosshair: '--rd-cross'
    };
    const DIGITS = {
        '0': 'abcdef', '1': 'bc', '2': 'abged', '3': 'abgcd', '4': 'fgbc',
        '5': 'afgcd', '6': 'afgedc', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg',
        '-': 'g', ' ': ''
    };

    const $ = (sel, root = document) => root.querySelector(sel);
    const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

    let ui = {};
    let locale = {};
    let prefs = { unit: 'kmh', mute: false, plates: true, limit: 0 };
    let plateReader = true;
    let history = [];
    let audio = null;
    let panelOpen = false;
    const antennaEls = {};
    const panelEls = {};

    const t = (key) => locale[key] || key;

    function post(name, data = {}) {
        return fetch(`https://${RESOURCE}/${name}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json; charset=UTF-8' },
            body: JSON.stringify(data)
        }).catch(() => {});
    }

    const SEGMENTS = (() => {
        const h = (y) => `12,${y} 17,${y - 5} 43,${y - 5} 48,${y} 43,${y + 5} 17,${y + 5}`;
        const v = (x, y1, y2) => `${x},${y1} ${x + 5},${y1 + 5} ${x + 5},${y2 - 5} ${x},${y2} ${x - 5},${y2 - 5} ${x - 5},${y1 + 5}`;
        return { a: h(6), b: v(53, 9, 49), c: v(53, 55, 95), d: h(98), e: v(7, 55, 95), f: v(7, 9, 49), g: h(52) };
    })();

    const glyphCache = {};
    function glyph(ch) {
        if (glyphCache[ch]) return glyphCache[ch];
        const lit = DIGITS[ch] ?? '';
        let shapes = '';
        for (const key of 'abcdefg') {
            shapes += `<polygon class="${lit.includes(key) ? 's-on' : 's-off'}" points="${SEGMENTS[key]}"/>`;
        }
        glyphCache[ch] = `<svg viewBox="0 0 60 104" style="transform:skewX(-6deg)">${shapes}</svg>`;
        return glyphCache[ch];
    }

    function setSeg(el, value, length = 3) {
        if (!el) return;
        let text = '';
        if (value !== null && value !== undefined && !Number.isNaN(Number(value))) {
            const max = Math.pow(10, length) - 1;
            text = String(Math.max(0, Math.min(max, Math.round(Number(value)))));
        }
        text = text.padStart(length, ' ');
        if (el.dataset.v === text) return;
        el.dataset.v = text;
        el.innerHTML = Array.from(text).map(glyph).join('');
    }

    function soundOn() {
        return ui.Sound && ui.Sound.Enabled && !prefs.mute;
    }

    function tone(freq, duration, at = 0, type = 'square', gain = 1) {
        if (!soundOn()) return;
        try {
            audio = audio || new (window.AudioContext || window.webkitAudioContext)();
        } catch (e) {
            return;
        }
        if (audio.state === 'suspended') audio.resume();
        const start = audio.currentTime + at;
        const volume = Math.max(0.0002, Math.min(1, Number(ui.Sound.Volume) || 0.3) * gain);
        const osc = audio.createOscillator();
        const amp = audio.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, start);
        amp.gain.setValueAtTime(0.0001, start);
        amp.gain.exponentialRampToValueAtTime(volume, start + 0.008);
        amp.gain.setValueAtTime(volume, start + duration - 0.02);
        amp.gain.exponentialRampToValueAtTime(0.0001, start + duration);
        osc.connect(amp);
        amp.connect(audio.destination);
        osc.start(start);
        osc.stop(start + duration + 0.02);
    }

    const SOUNDS = {
        alert: () => {
            tone(1320, 0.09, 0, 'square', 0.6);
            tone(1320, 0.09, 0.13, 'square', 0.6);
        },
        lock: () => tone(980, 0.14, 0, 'sine', 1),
        unlock: () => tone(620, 0.1, 0, 'sine', 0.8),
        click: () => tone(2400, 0.03, 0, 'sine', 0.25),
        bolo: () => {
            for (let i = 0; i < 3; i++) {
                tone(880, 0.13, i * 0.3, 'sawtooth', 0.5);
                tone(620, 0.13, i * 0.3 + 0.15, 'sawtooth', 0.5);
            }
        }
    };

    function factor() {
        return Math.min(window.innerWidth / 1920, window.innerHeight / 1080);
    }

    function place() {
        const el = $('#radar');
        const pos = ['top-left', 'top-right', 'bottom-left', 'bottom-right'].includes(ui.Position) ? ui.Position : 'bottom-right';
        const [vertical, horizontal] = pos.split('-');
        const f = factor();
        el.style.top = el.style.bottom = el.style.left = el.style.right = '';
        el.style[vertical] = `${(Number(ui.OffsetY) || 0) * f}px`;
        el.style[horizontal] = `${(Number(ui.OffsetX) || 0) * f}px`;
        el.style.transformOrigin = `${vertical} ${horizontal}`;
        const panel = $('#panel');
        const panelPositions = ['top-right', 'center-right', 'top-left', 'center-left'];
        const panelPos = panelPositions.includes(ui.ControlPanelPosition)
            ? ui.ControlPanelPosition
            : `top-${ui.PanelSide === 'left' ? 'left' : 'right'}`;
        const [panelVertical, side] = panelPos.split('-');
        panel.style.left = panel.style.right = '';
        panel.style[side] = `${40 * f}px`;
        if (panelVertical === 'center') {
            panel.style.top = '50%';
            panel.style.transform = 'translateY(-50%) scale(var(--rd-scale))';
            panel.style.transformOrigin = `${side} center`;
        } else {
            panel.style.top = '';
            panel.style.transform = '';
            panel.style.transformOrigin = `${side} top`;
        }
        document.documentElement.style.setProperty('--rd-scale', String((Number(ui.Scale) || 1) * f));
    }

    function applyTheme() {
        const root = document.documentElement.style;
        const colors = ui.Colors || {};
        for (const [key, cssVar] of Object.entries(COLOR_VARS)) {
            if (colors[key]) root.setProperty(cssVar, colors[key]);
        }
        if (ui.Opacity !== undefined) root.setProperty('--rd-opacity', String(ui.Opacity));
        if (ui.Radius !== undefined) root.setProperty('--rd-radius', `${ui.Radius}px`);
        if (ui.SpeedGun && ui.SpeedGun.PanelOffset !== undefined) root.setProperty('--rd-gun-offset', `${ui.SpeedGun.PanelOffset}px`);
        place();
    }

    function applyLocale() {
        $$('[data-l]').forEach((el) => { el.textContent = t(el.dataset.l); });
        $$('[data-ph]').forEach((el) => { el.placeholder = t(el.dataset.ph); });
    }

    function applyVisibility() {
        const show = ui.Show || {};
        $$('[data-show]').forEach((el) => {
            el.classList.toggle('off', show[el.dataset.show] === false);
        });
        if (!plateReader) {
            $$('.rd-plate-row').forEach((el) => el.classList.add('off'));
            $('#p-bolo').classList.add('off');
            $('#p-plates').classList.add('off');
        }
        const gun = ui.SpeedGun || {};
        $('#gun-plate-row').classList.toggle('off', gun.ShowPlate === false);
        $('#gun-dist-row').classList.toggle('off', gun.ShowDistance === false);
        $('#gun-history').classList.toggle('off', gun.History === false);
    }

    function buildAntennas() {
        const tpl = $('#tpl-antenna');
        const radarHost = $('#rd-antennas');
        const panelHost = $('#p-antennas');
        radarHost.innerHTML = '';
        panelHost.innerHTML = '';
        for (const name of ANTENNAS) {
            const node = tpl.content.firstElementChild.cloneNode(true);
            node.classList.add(name);
            $('.rd-ant-name', node).dataset.l = name === 'front' ? 'ui_front' : 'ui_rear';
            radarHost.appendChild(node);
            antennaEls[name] = {
                root: node,
                mode: $('.rd-ant-mode', node),
                state: $('.rd-ant-state', node),
                strong: $('[data-f="strong"]', node),
                fast: $('[data-f="fast"]', node),
                lock: $('[data-f="lock"]', node),
                lockWrap: $('.rd-lock', node),
                lockPlate: $('[data-f="lockPlate"]', node),
                plate: $('[data-f="plate"]', node),
                plateRow: $('.rd-plate-row', node)
            };

            const label = document.createElement('span');
            label.className = 'rd-ant-label';
            label.dataset.l = name === 'front' ? 'ui_front' : 'ui_rear';
            label.style.color = `var(${name === 'front' ? '--rd-front' : '--rd-rear'})`;
            const onBtn = makeButton('antenna', name);
            const modeBtn = makeButton('mode', name);
            const lockBtn = makeButton('lock', name);
            lockBtn.dataset.l = 'ui_lock';
            panelHost.append(label, onBtn, modeBtn, lockBtn);
            panelEls[name] = { on: onBtn, mode: modeBtn, lock: lockBtn };
        }
    }

    function makeButton(act, antenna) {
        const btn = document.createElement('button');
        btn.className = 'rd-btn';
        btn.dataset.act = act;
        btn.dataset.ant = antenna;
        return btn;
    }

    function unitLabel(unit) {
        return unit === 'mph' ? t('ui_mph') : t('ui_kmh');
    }

    function renderAntenna(name, d) {
        const el = antennaEls[name];
        if (!el || !d) return;
        el.root.classList.toggle('disabled', !d.on);
        el.root.classList.toggle('alert', !!d.alert);
        el.mode.textContent = d.mode === 'same' ? t('ui_same') : t('ui_opp');
        el.state.textContent = !d.on ? t('ui_off') : (d.lock ? t('ui_lock') : t('ui_on'));
        setSeg(el.strong, d.on ? d.strong : null);
        setSeg(el.fast, d.on ? d.fast : null);
        setSeg(el.lock, d.lock ? d.lock.speed : null);
        el.lockWrap.classList.toggle('empty', !d.lock);
        el.lockPlate.textContent = d.lock && d.lock.plate ? d.lock.plate : '';
        el.plate.textContent = d.plate || '--------';
        el.plateRow.classList.toggle('bolo', !!d.bolo);
        el.plateRow.classList.toggle('hidden', !prefs.plates);
    }

    function renderRadar(d) {
        if (!d) return;
        setSeg($('#rd-patrol'), d.patrol);
        setSeg($('#rd-limit'), d.limit);
        $('#rd-unit').textContent = unitLabel(d.unit);
        for (const name of ANTENNAS) renderAntenna(name, d[name]);
    }

    function renderPanel(s) {
        if (!s) return;
        prefs.mute = !!s.mute;
        prefs.plates = !!s.plates;
        prefs.unit = s.unit;
        $('#p-power').classList.toggle('active', !!s.power);
        for (const name of ANTENNAS) {
            const a = s[name] || {};
            const els = panelEls[name];
            els.on.textContent = a.on ? t('ui_on') : t('ui_off');
            els.on.classList.toggle('active', !!a.on);
            els.mode.textContent = a.mode === 'same' ? t('ui_same') : t('ui_opp');
            els.lock.classList.toggle('locked', !!a.locked);
        }
        setSeg($('#p-limit'), s.limit);
        $('#p-unit').textContent = unitLabel(s.unit);
        $('#p-plates').classList.toggle('active', !!s.plates);
        $('#p-mute').classList.toggle('active', !s.mute);
        $$('.rd-plate-row').forEach((el) => el.classList.toggle('hidden', !prefs.plates));
    }

    function renderBolos(list) {
        const host = $('#bolo-list');
        host.innerHTML = '';
        if (!list || list.length === 0) {
            const li = document.createElement('li');
            li.className = 'empty';
            li.textContent = t('ui_bolo_empty');
            host.appendChild(li);
            return;
        }
        for (const entry of list) {
            const li = document.createElement('li');
            const plate = document.createElement('span');
            plate.className = 'b-plate';
            plate.textContent = entry.plate;
            const reason = document.createElement('span');
            reason.className = 'b-reason';
            reason.textContent = entry.reason || '';
            reason.title = entry.reason || '';
            const scope = document.createElement('span');
            scope.className = 'b-scope';
            scope.textContent = t(entry.scope === 'global' ? 'ui_global' : entry.scope === 'shared' ? 'ui_shared' : 'ui_local');
            li.append(plate, reason, scope);
            if (entry.removable) {
                const del = document.createElement('button');
                del.className = 'b-del';
                del.dataset.plate = entry.plate;
                del.textContent = '×';
                li.appendChild(del);
            }
            host.appendChild(li);
        }
    }

    function renderGun(d) {
        const root = $('#gun');
        root.classList.toggle('hidden', !d.visible);
        root.classList.toggle('aiming', !!d.aiming);
        root.classList.toggle('locked', !!d.locked);
        root.classList.toggle('over', !!d.over && !d.locked);
        const hasReading = d.speed !== undefined && d.speed !== null;
        setSeg($('#gun-speed'), hasReading ? d.speed : null);
        $('#gun-unit').textContent = unitLabel(d.unit);
        $('#gun-dist').textContent = hasReading ? `${d.dist} ${d.distUnit}` : '---';
        $('#gun-plate').textContent = hasReading ? (d.plate || '--------') : t('ui_no_target');
    }

    function addHistory(entry) {
        const gun = ui.SpeedGun || {};
        if (gun.History === false) return;
        const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
        const last = history[0];
        if (last && last.time === time && last.plate === entry.plate && last.speed === entry.speed) return;
        history.unshift({ time, speed: entry.speed, unit: entry.unit, plate: entry.plate });
        history = history.slice(0, Math.max(1, Number(gun.HistorySize) || 5));
        const host = $('#gun-history-list');
        host.innerHTML = '';
        for (const item of history) {
            const li = document.createElement('li');
            const timeEl = document.createElement('span');
            timeEl.textContent = item.time;
            const speedEl = document.createElement('span');
            speedEl.className = 'h-speed';
            speedEl.textContent = `${item.speed} ${unitLabel(item.unit)}`;
            const plateEl = document.createElement('span');
            plateEl.textContent = item.plate || '--------';
            li.append(timeEl, speedEl, plateEl);
            host.appendChild(li);
        }
    }

    function setPanel(open, state) {
        panelOpen = open;
        $('#panel').classList.toggle('hidden', !open);
        if (open) renderPanel(state);
        else document.activeElement && document.activeElement.blur();
    }

    const handlers = {
        init(data) {
            ui = data.ui || {};
            locale = data.locale || {};
            prefs = Object.assign(prefs, data.prefs || {});
            plateReader = data.plateReader !== false;
            buildAntennas();
            applyLocale();
            applyTheme();
            applyVisibility();
            if (data.allowUnit === false) $('#p-unit').classList.add('off');
            setSeg($('#rd-patrol'), null);
            setSeg($('#rd-limit'), prefs.limit);
            setSeg($('#gun-speed'), null);
            renderBolos([]);
        },
        radar(data) {
            $('#radar').classList.toggle('hidden', !data.visible);
        },
        radarData(data) {
            renderRadar(data.data);
        },
        panel(data) {
            setPanel(!!data.open, data.state);
        },
        panelState(data) {
            renderPanel(data.state);
        },
        prefs(data) {
            Object.assign(prefs, data.prefs || {});
        },
        bolos(data) {
            renderBolos(data.list);
        },
        sound(data) {
            const fn = SOUNDS[data.name];
            if (fn) fn();
        },
        gun(data) {
            renderGun(data);
        },
        gunHistory(data) {
            addHistory(data);
        }
    };

    window.addEventListener('message', (event) => {
        const data = event.data;
        if (!data || typeof data.action !== 'string') return;
        const handler = handlers[data.action];
        if (handler) handler(data);
    });

    document.addEventListener('click', (event) => {
        if (!panelOpen) return;
        const del = event.target.closest('.b-del');
        if (del) {
            SOUNDS.click();
            post('boloRemove', { plate: del.dataset.plate });
            return;
        }
        const btn = event.target.closest('[data-act]');
        if (!btn) return;
        SOUNDS.click();
        if (btn.dataset.act === 'close') {
            post('close');
            return;
        }
        post('action', {
            type: btn.dataset.act,
            antenna: btn.dataset.ant,
            delta: Number(btn.dataset.delta) || 0
        });
    });

    $('#bolo-form').addEventListener('submit', (event) => {
        event.preventDefault();
        const plateInput = $('#bolo-plate');
        const reasonInput = $('#bolo-reason');
        const plate = plateInput.value.trim();
        if (!plate) return;
        SOUNDS.click();
        post('boloAdd', { plate, reason: reasonInput.value.trim() });
        plateInput.value = '';
        reasonInput.value = '';
    });

    document.addEventListener('keydown', (event) => {
        if (panelOpen && event.key === 'Escape') post('close');
    });

    window.addEventListener('resize', () => {
        if (ui.Position !== undefined) place();
    });

    post('ready');
})();

