const page = document.querySelector('.access-page');
const seconds = Math.max(1, Number(page?.dataset.redirectSeconds) || 10);
const counter = document.querySelector('[data-countdown]');
const bar = document.querySelector('.access-bar');

if (bar) bar.style.animationDuration = `${seconds}s`;

let remaining = seconds;
if (counter) counter.textContent = String(remaining);

const timer = window.setInterval(() => {
  remaining -= 1;
  if (counter) counter.textContent = String(Math.max(0, remaining));
  if (remaining <= 0) window.clearInterval(timer);
}, 1000);

window.setTimeout(() => {
  window.location.replace('/');
}, seconds * 1000);
